/* Open Note — lib/nuclide.js
   the chart of the nuclides, as data: every nuclide that has ever been made or
   found, what it decays into and how fast. js/items/nuchart.js draws with this;
   nothing here draws.

   Where chem.js answers "what is this element" and stops at the electrons, this
   file is about the nucleus: 3558 ground states and 2088 metastable states, laid
   out on the plane that physicists actually use — neutrons across, protons up —
   where the periodic table is only the projection onto one axis.

   ---- the source ----
   NUBASE2020 (F.G. Kondev, M. Wang, W.J. Huang, S. Naimi, G. Audi,
   Chin. Phys. C45, 030001 (2021)), the evaluated table behind every wall chart,
   packed to one line per nuclide under a line per element:

     @Z Sym                         the element the lines under it belong to
     A[m]  ME  T   Jpi  decay  ab yr

     A      mass number; a trailing letter is a metastable state, m before n
            before p, q, x — NUBASE's own ordering by excitation energy
     ME     mass excess in keV, rounded to the keV; a trailing # means the
            value is from systematics rather than measured. Everything else a
            chart wants — Q values, separation energies, binding energy per
            nucleon — is arithmetic on these, so they are not stored twice.
     T      half-life, value and unit run together (211.1ky, 6.0066h, 233ns);
            stbl for stable, punst for particle-unstable, - for unknown. A
            leading <, > or ~ is a limit and is kept.
     Jpi    spin and parity, in brackets where the assignment is tentative
     decay  the branches, strongest first: B-=100;B-n=0.50. = is a measured
            branch, ~ approximate, < or > a limit, ? a branch that is known to
            happen but not how often.
     ab     isotopic abundance in per cent, - for a nuclide that is not in
            nature (ground states only)
     yr     year of discovery (ground states only)
     exc    for a metastable state, its excitation energy in keV, in place of
            the abundance and the year

   Modes are NUBASE's spelling: B- beta minus, B+ positron, EC electron
   capture, A alpha, p and n emission, SF spontaneous fission, IT the isomeric
   transition down to the ground state, and the compounds — B-n, B+p, ECP,
   B-A — where a beta decay leaves the daughter unbound and it immediately
   throws a nucleon. The cluster decays keep their nuclide's name: 14C, 24Ne,
   34Si. All of them are turned into a step across the chart by NUC_STEP. */
